<?php
// All data access and status changes are authenticated by api.php. No secrets here.
header('Cache-Control: no-store, private, max-age=0');
header('X-Robots-Tag: noindex, nofollow');
header('X-Frame-Options: SAMEORIGIN');
header('X-Content-Type-Options: nosniff');
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>ZeroBooze — Feedback Review</title><style>
*{box-sizing:border-box}body{margin:0;background:#f6f4ed;color:#08082e;font-family:Arial,sans-serif}main{max-width:1200px;margin:auto;padding:40px 25px}h1{font-weight:500;font-size:35px;letter-spacing:-1px}p{font-size:13px;line-height:1.8;color:#607176}input,select,button{font:inherit;padding:10px 13px;border:1px solid #dce0d9;border-radius:6px;background:#fffef9;color:#08082e}button{cursor:pointer;background:#e9e5d4}button:disabled{opacity:.6}label{font-size:12px;display:block}label input{display:block;margin:9px 0 15px;width:100%;max-width:420px}form.filters,.tools{display:flex;gap:10px;flex-wrap:wrap;margin:22px 0}article{padding:23px 0;border-top:1px solid #dce0d9}article h2{font-size:20px;font-weight:500}article .body{white-space:pre-wrap;line-height:1.8;font-size:14px;overflow-wrap:anywhere;max-width:950px}.meta{font-size:11px;color:#607176;line-height:1.8}.badge{display:inline-block;background:#e9e5d4;padding:4px 7px;border-radius:4px;margin-left:8px}.message{padding:12px 0;font-size:13px;line-height:1.7}a{color:inherit}.note{font-size:11px}.top{display:flex;justify-content:space-between;gap:20px;align-items:center}.pager{display:flex;gap:15px;align-items:center;margin:25px 0;font-size:12px}[hidden]{display:none!important}.login{padding:25px;background:#fffef9;border:1px solid #dce0d9;border-radius:10px;max-width:550px}@media(max-width:650px){.top{display:block}.filters>*{width:100%}h1{font-size:29px}}
</style></head><body><main><div class="top"><div><p>ZeroBooze / Content hub</p><h1>Feedback review</h1></div><a href="./">Back to the hub ↗</a></div><div id="message" class="message" role="status"></div><section class="login" id="login"><h2>Team sign-in</h2><p>Use the dashboard password set during installation. Reviewer names are self-reported, not verified accounts.</p><form id="login-form"><label>Dashboard password<input type="password" id="password" autocomplete="current-password" required></label><button>Sign in</button></form></section><section id="dashboard" hidden><p>Feedback and questionnaire answers from all reviewers. Dates below are shown in UTC. Export CSV to open in Excel or Google Sheets.</p><form class="filters" id="filters"><select id="status" aria-label="Status"><option value="">All statuses</option><option value="open">Open</option><option value="resolved">Resolved</option></select><select id="kind" aria-label="Type"><option value="">All types</option><option value="comment">Comments</option><option value="answer">Questionnaire answers</option></select><input id="query" aria-label="Search feedback" placeholder="Search section, name, or feedback"><button>Apply filters</button></form><div class="tools"><button id="refresh">Refresh</button><button id="export">Export filtered CSV</button><button id="logout">Sign out</button></div><div id="summary" class="meta"></div><div id="rows"></div><div class="pager"><button id="prev">Previous</button><span id="page-label"></span><button id="next">Next</button></div></section></main><script>
const el=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let csrf='',page=1,total=0;
async function api(action,data){let url=new URL('api.php',location.href);url.searchParams.set('action',action);if(action==='list'||action==='export'){url.searchParams.set('status',el('status').value);url.searchParams.set('kind',el('kind').value);url.searchParams.set('q',el('query').value);url.searchParams.set('page',page)}if(action==='export'){location.href=url;return}const opts={credentials:'same-origin',cache:'no-store'};if(data){opts.method='POST';opts.headers={'Content-Type':'application/json'};opts.body=JSON.stringify({...data,csrf})}const response=await fetch(url,opts);const r=await response.json();if(r.csrf)csrf=r.csrf;if(!response.ok){if(response.status===401){el('dashboard').hidden=true;el('login').hidden=false}throw Error(r.error||'Unable to complete that action.')}return r}
function message(t){el('message').textContent=t}
async function refresh(){try{const r=await api('list');total=r.total;el('rows').innerHTML=r.rows.length?r.rows.map(row=>`<article><div class="meta">#${row.id} · ${esc(row.kind)}<span class="badge">${esc(row.status)}</span></div><h2>${esc(row.resource_title)}</h2><div class="meta">${esc(row.reviewer_name)}${row.reviewer_email?' · '+esc(row.reviewer_email):''}<br>${esc(row.created_at)} UTC</div><p class="body">${esc(row.body)}</p><button data-id="${Number(row.id)}" data-status="${row.status==='resolved'?'open':'resolved'}">${row.status==='resolved'?'Reopen':'Mark resolved'}</button></article>`).join(''):'<p>No feedback matches these filters.</p>';el('summary').textContent=total+' submissions';el('page-label').textContent='Page '+page+' of '+Math.max(1,Math.ceil(total/50));el('prev').disabled=page<=1;el('next').disabled=page*50>=total;document.querySelectorAll('[data-id]').forEach(b=>b.onclick=async()=>{b.disabled=true;try{await api('resolve',{id:Number(b.dataset.id),status:b.dataset.status});message('Status updated.');await refresh()}catch(e){message(e.message);b.disabled=false}});el('login').hidden=true;el('dashboard').hidden=false}catch(e){message(e.message)}}
el('login-form').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{await api('login',{password:el('password').value});el('password').value='';message('Signed in.');await refresh()}catch(e){message(e.message)}finally{b.disabled=false}};el('filters').onsubmit=e=>{e.preventDefault();page=1;refresh()};el('refresh').onclick=refresh;el('export').onclick=()=>api('export');el('prev').onclick=()=>{if(page>1){page--;refresh()}};el('next').onclick=()=>{if(page*50<total){page++;refresh()}};el('logout').onclick=async()=>{try{await api('logout',{});el('dashboard').hidden=true;el('login').hidden=false;el('rows').textContent='';message('Signed out.')}catch(e){message(e.message)}};api('session').then(r=>{if(r.admin)refresh();else message('Ready to sign in.')}).catch(e=>{message(e.message);el('login-form').querySelector('button').disabled=true});
</script></body></html>
